from __future__ import annotations
from dataclasses import asdict, dataclass
import shutil
from typing import Any

@dataclass(frozen=True)
class ToolSpec:
    name: str
    category: str
    purpose: str
    executable: str
    mode: str = "offline"
    open_source: bool = True
    adapter: str = "generic"
    source_kind: str = "project"
    homepage: str = ""


def _spec(name: str, category: str, purpose: str, executable: str, mode: str = "offline", adapter: str = "generic", homepage: str = "", open_source: bool = True, source_kind: str = "project") -> ToolSpec:
    return ToolSpec(name, category, purpose, executable, mode, open_source, adapter, source_kind, homepage)

