non_oss={
    "NetworkMiner","Binary Ninja Community","Any.Run community connector","F-Response Community","THOR Lite",
    "UnpacMe connectors","ReversingLabs rules adapters","SOC Prime Uncoder Community","KAPE","KAPE modules"
}

_specs: list[ToolSpec] = []
_seen: set[tuple[str,str]] = set()
for category, items in _GROUPS.items():
    for name, purpose, exe, *rest in items:
        mode = rest[0] if rest and rest[0] in {"connector", "offline"} else "offline"
        key=(name,category)
        if key not in _seen:
            _specs.append(_spec(name,category,purpose,exe,mode,adapter="generic"))
            _seen.add(key)
for name,purpose,exe,category in EXTRA:
    key=(name,category)
    if key not in _seen:
        _specs.append(_spec(name,category,purpose,exe,"connector" if "API" in name or "feed" in name.lower() or "connector" in name.lower() else "offline"))
        _seen.add(key)

# A few entries are intentionally retained as connector/compatibility references even
# though the upstream project is not itself open-source. They are marked so the UI
# never misrepresents them as OSS.
_adjusted=[]
for _item in _specs:
    if _item.name in non_oss:
        _adjusted.append(ToolSpec(_item.name,_item.category,_item.purpose,_item.executable,_item.mode,False,_item.adapter,"reference",_item.homepage))
    elif _item.name in {"REMnux","FLARE-VM","Security Onion","SIFT tools","CAINE tools","Kali forensic tools"}:
        _adjusted.append(ToolSpec(_item.name,_item.category,_item.purpose,_item.executable,_item.mode,True,_item.adapter,"distribution",_item.homepage))
    elif _item.name in {"Sigma","STIX2","STIX 2.1","TAXII 2.1","OCSF","ECS schema","MITRE ATT&CK STIX","ATT&CK Navigator","ATT&CK Workbench","Attack Flow","YARA-Rules","SigmaHQ","MISP Galaxy Clusters","MISP Warninglists"}:
        _adjusted.append(ToolSpec(_item.name,_item.category,_item.purpose,_item.executable,_item.mode,True,_item.adapter,"data/specification",_item.homepage))
    else:
        _adjusted.append(_item)
_specs=_adjusted
TOOL_CATALOG: tuple[ToolSpec, ...] = tuple(_specs)


def catalog() -> list[dict[str, Any]]:
    rows=[]
    for spec in TOOL_CATALOG:
        path = shutil.which(spec.executable) if spec.executable not in {"python","git","docker","curl"} else shutil.which(spec.executable)
        row=asdict(spec)
        row["installed"] = bool(path)
        row["resolved_path"] = path
        row["status"] = "ready" if path else ("connector" if spec.mode == "connector" else "not_installed")
        rows.append(row)
    return rows


def summary() -> dict[str, Any]:
    rows=catalog()
    categories=sorted({x["category"] for x in rows})
    return {
        "catalog_version":"18.0.0",
        "tool_count":len(rows),
        "installed_count":sum(1 for x in rows if x["installed"]),
        "open_source_count":sum(1 for x in rows if x["open_source"]),
        "reference_count":sum(1 for x in rows if not x["open_source"]),
        "connector_count":sum(1 for x in rows if x["mode"]=="connector"),
        "categories":categories,
        "execution_policy":"Adapters are opt-in. No third-party tool is executed automatically during passive analysis.",
        "license_note":"Catalog entries are intended for open-source/community tooling and adapters; verify the current project license before redistribution or commercial deployment.",
    }
